import React, { useState, useEffect, useCallback } from "react";
import {
  Search, MapPin, Phone, ShoppingCart, Plus, Minus,
  ArrowRight, Trash2, Package, Home, ClipboardList, Check, ShieldCheck, Star, Lock,
} from "lucide-react";
import { supabase } from "./supabaseClient";

const SPLASH_IMG = "data:image/jpeg;base64,";
const LOGO_SRC = "data:image/png;base64,";

const PALETTE = {
  cream: "#FDF6EC",
  ink: "#3A2A1F",
  orange: "#D15527", orangeDark: "#8C3714",
  green: "#4B7B4F", greenDark: "#2F5A32",
  gold: "#E0A030", goldDark: "#8A5A10",
  teal: "#2F8F86", tealDark: "#1D5C56",
  red: "#C23B22", redDark: "#8C2A17",
};

const CATS = [
  { id: "طبخ يومي", label: "طبخ يومي" },
  { id: "مونة", label: "مونة" },
  { id: "حلويات", label: "حلويات" },
  { id: "معجنات", label: "معجنات" },
  { id: "مناسف وعزايم", label: "مناسف وعزايم" },
];

const CAT_STYLE = {
  "طبخ يومي": { bg: "#FBE4D8", text: PALETTE.orangeDark, solid: PALETTE.orange },
  "مونة": { bg: "#E4F0E1", text: PALETTE.greenDark, solid: PALETTE.green },
  "حلويات": { bg: "#FBEED2", text: PALETTE.goldDark, solid: PALETTE.gold },
  "معجنات": { bg: "#DCF1EF", text: PALETTE.tealDark, solid: PALETTE.teal },
  "مناسف وعزايم": { bg: "#FADBD3", text: PALETTE.redDark, solid: PALETTE.red },
};
function catStyle(cat) {
  return CAT_STYLE[cat] || { bg: "#EFEAE3", text: PALETTE.ink, solid: PALETTE.ink };
}
const primaryBtn = { backgroundColor: PALETTE.orange, color: "#FFF8F0" };

const uid = () => Math.random().toString(36).slice(2, 10);

// "my kitchen" is remembered on this device only — real browser localStorage
async function loadPersonal(key) {
  try { return localStorage.getItem("tabkha_" + key); } catch (e) { return null; }
}
async function savePersonal(key, value) {
  try { localStorage.setItem("tabkha_" + key, value); } catch (e) { console.error(e); }
}

function mapItem(it) {
  return { id: it.id, houseId: it.house_id, name: it.name, category: it.category, price: it.price, qty: it.qty };
}
function mapOrder(o) {
  return {
    id: o.id, houseId: o.house_id, houseName: o.house_name, items: o.items,
    total: o.total, address: o.address, note: o.note, status: o.status, createdAt: o.created_at,
  };
}
function mapAd(a) {
  return { id: a.id, houseId: a.house_id, houseName: a.house_name, text: a.text, pkg: a.pkg, createdAt: a.created_at, expiresAt: a.expires_at };
}

const AD_PACKAGES = {
  "أساسي": { days: 3, label: "أساسي", solid: "#A8A29E" },
  "مميز": { days: 7, label: "مميز", solid: "#E0A030" },
  "حصري": { days: 14, label: "حصري", solid: "#D15527" },
};

export default function TabkhaApp() {
  const [splash, setSplash] = useState(true);
  useEffect(() => {
    const t = setTimeout(() => setSplash(false), 2200);
    return () => clearTimeout(t);
  }, []);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [houses, setHouses] = useState([]);
  const [items, setItems] = useState([]);
  const [orders, setOrders] = useState([]);
  const [ads, setAds] = useState([]);
  const [myHouseId, setMyHouseId] = useState(null);

  const [tab, setTab] = useState("browse");
  const [activeHouseId, setActiveHouseId] = useState(null);
  const [activeCat, setActiveCat] = useState(null);
  const [query, setQuery] = useState("");
  const [cart, setCart] = useState([]);
  const [checkout, setCheckout] = useState(false);
  const [address, setAddress] = useState("");
  const [note, setNote] = useState("");
  const [orderDone, setOrderDone] = useState(false);
  const [houseTab, setHouseTab] = useState(null);

  const [ordersHouseId, setOrdersHouseId] = useState("");

  const refreshAll = useCallback(async () => {
    setLoadError("");
    try {
      const [housesRes, itemsRes, ordersRes, adsRes, mine] = await Promise.all([
        supabase.from("houses").select("*").order("created_at", { ascending: false }),
        supabase.from("items").select("*"),
        supabase.from("orders").select("*").order("created_at", { ascending: false }),
        supabase.from("ads").select("*").order("created_at", { ascending: false }),
        loadPersonal("myHouseId"),
      ]);
      if (housesRes.error) throw housesRes.error;
      if (itemsRes.error) throw itemsRes.error;
      if (ordersRes.error) throw ordersRes.error;
      setHouses(housesRes.data || []);
      setItems((itemsRes.data || []).map(mapItem));
      setOrders((ordersRes.data || []).map(mapOrder));
      setAds(((adsRes && adsRes.data) || []).map(mapAd));
      if (mine) setMyHouseId(mine);
    } catch (e) {
      console.error(e);
      setLoadError("تعذر تحميل البيانات، تأكد من إعدادات Supabase.");
    }
    setLoading(false);
  }, []);

  useEffect(() => { refreshAll(); }, [refreshAll]);

  const filteredHouses = houses
    .filter((h) => (h.status || "معتمد") === "معتمد")
    .filter((h) => {
      const matchesCat = !activeCat || (h.categories || []).includes(activeCat);
      const matchesQuery = !query || h.name.includes(query) || (h.area || "").includes(query);
      return matchesCat && matchesQuery;
    })
    .sort((a, b) => (b.featured ? 1 : 0) - (a.featured ? 1 : 0));

  const activeHouse = houses.find((h) => h.id === activeHouseId);
  const houseItems = items.filter((it) => it.houseId === activeHouseId);
  const houseCats = [...new Set(houseItems.map((it) => it.category))];

  function openHouse(id) {
    setActiveHouseId(id);
    setCart([]);
    setCheckout(false);
    setOrderDone(false);
    const cats = [...new Set(items.filter((it) => it.houseId === id).map((it) => it.category))];
    setHouseTab(cats[0] || null);
  }

  function addToCart(itemId) {
    setCart((c) => {
      const existing = c.find((x) => x.itemId === itemId);
      if (existing) return c.map((x) => x.itemId === itemId ? { ...x, qty: x.qty + 1 } : x);
      return [...c, { itemId, qty: 1 }];
    });
  }
  function changeQty(itemId, delta) {
    setCart((c) => c
      .map((x) => x.itemId === itemId ? { ...x, qty: x.qty + delta } : x)
      .filter((x) => x.qty > 0));
  }
  const cartCount = cart.reduce((s, x) => s + x.qty, 0);
  const cartLines = cart.map((c) => {
    const item = items.find((it) => it.id === c.itemId);
    return item ? { ...item, qty: c.qty } : null;
  }).filter(Boolean);
  const cartTotal = cartLines.reduce((s, l) => s + l.price * l.qty, 0);
  const deliveryFee = cartLines.length ? 5000 : 0;

  async function confirmOrder() {
    if (!address.trim() || !activeHouse) return;
    const payload = {
      house_id: activeHouse.id,
      house_name: activeHouse.name,
      items: cartLines.map((l) => ({ name: l.name, qty: l.qty, price: l.price })),
      total: cartTotal + deliveryFee,
      address, note,
      status: "قيد التحضير",
    };
    const { data, error } = await supabase.from("orders").insert([payload]).select();
    if (!error && data && data[0]) setOrders((prev) => [mapOrder(data[0]), ...prev]);
    setOrderDone(true);
    setCart([]);
    setAddress(""); setNote("");
  }

  const [regName, setRegName] = useState("");
  const [regArea, setRegArea] = useState("");
  const [regPhone, setRegPhone] = useState("");
  const [regDesc, setRegDesc] = useState("");
  const [regCats, setRegCats] = useState([]);
  const [regItems, setRegItems] = useState([{ name: "", category: "", price: "", qty: "" }]);
  const [regDone, setRegDone] = useState(false);
  const [regError, setRegError] = useState("");

  function toggleRegCat(c) {
    setRegCats((cs) => cs.includes(c) ? cs.filter((x) => x !== c) : [...cs, c]);
  }
  function updateRegItem(idx, field, val) {
    setRegItems((list) => list.map((it, i) => i === idx ? { ...it, [field]: val } : it));
  }
  function addRegItemRow() {
    setRegItems((list) => [...list, { name: "", category: regCats[0] || "", price: "", qty: "" }]);
  }
  function removeRegItemRow(idx) {
    setRegItems((list) => list.filter((_, i) => i !== idx));
  }

  async function submitRegistration() {
    setRegError("");
    if (!regName.trim() || !regArea.trim() || regCats.length === 0) {
      setRegError("لازم إدخال اسم بيت الطبخ، المنطقة، واختيار اختصاص واحد عالأقل.");
      return;
    }
    const validItems = regItems.filter((it) => it.name.trim() && it.category && it.price);
    if (validItems.length === 0) {
      setRegError("لازم إضافة صنف واحد عالأقل معه اسم، تصنيف، وسعر.");
      return;
    }
    const { data: houseData, error: houseErr } = await supabase.from("houses").insert([{
      name: regName.trim(), area: regArea.trim(), phone: regPhone.trim(),
      description: regDesc.trim(), categories: regCats,
      status: "قيد المراجعة", featured: false,
    }]).select();
    if (houseErr || !houseData || !houseData[0]) {
      setRegError("صار في مشكلة بالحفظ، حاول مرة تانية.");
      return;
    }
    const houseId = houseData[0].id;
    const itemsPayload = validItems.map((it) => ({
      house_id: houseId, name: it.name.trim(), category: it.category,
      price: Number(it.price) || 0, qty: Number(it.qty) || 0,
    }));
    const { data: itemsData, error: itemsErr } = await supabase.from("items").insert(itemsPayload).select();
    setHouses((prev) => [houseData[0], ...prev]);
    if (!itemsErr && itemsData) setItems((prev) => [...prev, ...itemsData.map(mapItem)]);
    await savePersonal("myHouseId", houseId);
    setMyHouseId(houseId);
    setRegDone(true);
    setRegName(""); setRegArea(""); setRegPhone(""); setRegDesc("");
    setRegCats([]); setRegItems([{ name: "", category: "", price: "", qty: "" }]);
  }

  const [kNewItem, setKNewItem] = useState({ name: "", category: "", price: "", qty: "" });
  async function addKitchenItem() {
    if (!myHouseId || !kNewItem.name.trim() || !kNewItem.category || !kNewItem.price) return;
    const { data, error } = await supabase.from("items").insert([{
      house_id: myHouseId, name: kNewItem.name.trim(), category: kNewItem.category,
      price: Number(kNewItem.price) || 0, qty: Number(kNewItem.qty) || 0,
    }]).select();
    if (!error && data && data[0]) setItems((prev) => [...prev, mapItem(data[0])]);
    setKNewItem({ name: "", category: "", price: "", qty: "" });
  }
  async function deleteKitchenItem(itemId) {
    const { error } = await supabase.from("items").delete().eq("id", itemId);
    if (!error) setItems((prev) => prev.filter((it) => it.id !== itemId));
  }

  const myOrders = orders.filter((o) => o.houseId === ordersHouseId);
  async function toggleOrderStatus(orderId) {
    const order = orders.find((o) => o.id === orderId);
    if (!order) return;
    const newStatus = order.status === "قيد التحضير" ? "تم التسليم" : "قيد التحضير";
    const { error } = await supabase.from("orders").update({ status: newStatus }).eq("id", orderId);
    if (!error) setOrders((prev) => prev.map((o) => o.id === orderId ? { ...o, status: newStatus } : o));
  }

  const [adminUnlocked, setAdminUnlocked] = useState(false);
  const [adminPass, setAdminPass] = useState("");
  const [adminError, setAdminError] = useState("");
  const DEMO_ADMIN_PASSWORD = "1234";
  function checkAdminPass() {
    if (adminPass === DEMO_ADMIN_PASSWORD) { setAdminUnlocked(true); setAdminError(""); }
    else setAdminError("كلمة السر غلط.");
  }
  const pendingHouses = houses.filter((h) => (h.status || "معتمد") !== "معتمد");
  const approvedHouses = houses.filter((h) => (h.status || "معتمد") === "معتمد");
  async function approveHouse(id) {
    const { error } = await supabase.from("houses").update({ status: "معتمد" }).eq("id", id);
    if (!error) setHouses((prev) => prev.map((h) => h.id === id ? { ...h, status: "معتمد" } : h));
  }
  async function rejectHouse(id) {
    await supabase.from("items").delete().eq("house_id", id);
    const { error } = await supabase.from("houses").delete().eq("id", id);
    if (!error) {
      setHouses((prev) => prev.filter((h) => h.id !== id));
      setItems((prev) => prev.filter((it) => it.houseId !== id));
    }
  }
  async function toggleFeatured(id) {
    const house = houses.find((h) => h.id === id);
    if (!house) return;
    const { error } = await supabase.from("houses").update({ featured: !house.featured }).eq("id", id);
    if (!error) setHouses((prev) => prev.map((h) => h.id === id ? { ...h, featured: !h.featured } : h));
  }

  const [adHouseId, setAdHouseId] = useState("");
  const [adText, setAdText] = useState("");
  const [adPackage, setAdPackage] = useState("أساسي");
  const activeAds = ads.filter((a) => new Date(a.expiresAt) > new Date());
  async function createAd() {
    if (!adHouseId || !adText.trim()) return;
    const house = houses.find((h) => h.id === adHouseId);
    const days = AD_PACKAGES[adPackage].days;
    const payload = {
      house_id: adHouseId, house_name: house ? house.name : "",
      text: adText.trim(), pkg: adPackage,
      expires_at: new Date(Date.now() + days * 86400000).toISOString(),
    };
    const { data, error } = await supabase.from("ads").insert([payload]).select();
    if (!error && data && data[0]) setAds((prev) => [mapAd(data[0]), ...prev]);
    setAdText(""); setAdHouseId("");
  }
  async function deleteAd(id) {
    const { error } = await supabase.from("ads").delete().eq("id", id);
    if (!error) setAds((prev) => prev.filter((a) => a.id !== id));
  }

  const fontStyle = { fontFamily: "'Tajawal', sans-serif" };
  const titleFontStyle = { fontFamily: "'Lalezar', sans-serif" };
  const fontImport = "@import url('https://fonts.googleapis.com/css2?family=Lalezar&family=Tajawal:wght@400;500;700&display=swap');";

  if (splash) {
    return (
      <div dir="rtl" style={fontStyle}
        className="max-w-md mx-auto min-h-[600px] rounded-3xl overflow-hidden border border-stone-200">
        <style>{fontImport}</style>
        <img src={SPLASH_IMG} alt="طبخة — من مطبخك لقلوب الناس" className="w-full h-full object-cover" />
      </div>
    );
  }

  if (loading) {
    return (
      <div dir="rtl" style={{ ...fontStyle, backgroundColor: PALETTE.cream }} className="flex items-center justify-center py-24 text-stone-500">
        <style>{fontImport}</style>
        عم يتجهز طبخة...
      </div>
    );
  }

  return (
    <div dir="rtl" style={{ ...fontStyle, backgroundColor: PALETTE.cream }} className="max-w-md mx-auto min-h-[600px] rounded-3xl overflow-hidden border border-stone-200 flex flex-col">
      <style>{fontImport}</style>

      <div style={{ backgroundColor: PALETTE.orange }} className="px-5 py-4 flex items-center gap-2">
        <img src={LOGO_SRC} alt="طبخة" className="w-8 h-8 object-contain" />
        <span style={{ ...titleFontStyle, color: "#FFF8F0" }} className="text-2xl">طبخة</span>
      </div>

      <div className="flex-1 overflow-y-auto p-4">

        {tab === "browse" && !activeHouseId && (
          <div>
            {activeAds.length > 0 && (
              <div className="mb-4">
                {activeAds.filter((a) => a.pkg === "حصري").slice(0, 1).map((a) => (
                  <div key={a.id} style={{ backgroundColor: AD_PACKAGES["حصري"].solid }}
                    className="rounded-2xl p-4 text-white mb-2">
                    <div className="text-[11px] opacity-80 mb-1">إعلان حصري</div>
                    <div className="font-semibold text-base mb-1">{a.houseName}</div>
                    <div className="text-sm opacity-95">{a.text}</div>
                  </div>
                ))}
                <div className="flex gap-2 overflow-x-auto pb-1">
                  {activeAds.filter((a) => a.pkg !== "حصري").map((a) => (
                    <div key={a.id}
                      style={{ backgroundColor: AD_PACKAGES[a.pkg].solid + "1A", borderColor: AD_PACKAGES[a.pkg].solid }}
                      className="border rounded-xl p-2.5 min-w-[190px] max-w-[220px] flex-shrink-0">
                      <div className="text-[11px] font-medium mb-0.5" style={{ color: AD_PACKAGES[a.pkg].solid }}>{a.pkg} · {a.houseName}</div>
                      <div className="text-xs text-stone-600 line-clamp-2">{a.text}</div>
                    </div>
                  ))}
                </div>
              </div>
            )}
            <div className="flex items-center gap-2 bg-white border border-stone-200 rounded-xl px-3 py-2 mb-3">
              <Search size={18} className="text-stone-400" />
              <input
                value={query} onChange={(e) => setQuery(e.target.value)}
                placeholder="ابحث عن بيت طبخ أو منطقة"
                className="flex-1 bg-transparent outline-none text-sm placeholder-stone-400"
              />
            </div>
            <div className="flex gap-2 overflow-x-auto mb-4 pb-1">
              <button onClick={() => setActiveCat(null)}
                style={!activeCat ? primaryBtn : {}}
                className={`text-sm px-3 py-1.5 rounded-full whitespace-nowrap ${!activeCat ? "" : "bg-white border border-stone-200 text-stone-500"}`}>الكل</button>
              {CATS.map((c) => (
                <button key={c.id} onClick={() => setActiveCat(c.id)}
                  style={activeCat === c.id ? { backgroundColor: catStyle(c.id).solid, color: "#fff" } : {}}
                  className={`text-sm px-3 py-1.5 rounded-full whitespace-nowrap ${activeCat === c.id ? "" : "bg-white border border-stone-200 text-stone-500"}`}>
                  {c.label}
                </button>
              ))}
            </div>

            {filteredHouses.length === 0 && (
              <div className="text-center text-stone-400 text-sm py-16">
                <Package className="mx-auto mb-2" size={28} />
                ولا بيت طبخ مسجل هلق بهاي الفئة.<br />أول ما حدا يسجل رح يطلع هون.
              </div>
            )}

            <div className="flex flex-col gap-3">
              {filteredHouses.map((h) => (
                <button key={h.id} onClick={() => openHouse(h.id)}
                  className="flex gap-3 bg-white border border-stone-200 rounded-2xl p-3 text-right shadow-sm hover:border-stone-300 transition">
                  <div style={{ backgroundColor: catStyle((h.categories || [])[0]).solid }} className="w-16 h-16 rounded-xl flex items-center justify-center flex-shrink-0">
                    <img src={LOGO_SRC} alt="" className="w-9 h-9 object-contain" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="font-semibold text-stone-900 text-base flex items-center gap-1">
                      {h.name}
                      {h.featured && <Star size={13} fill={PALETTE.gold} style={{ color: PALETTE.gold }} />}
                    </div>
                    <div className="text-sm text-stone-500 flex items-center gap-1 mt-0.5">
                      <MapPin size={12} /> {h.area}
                    </div>
                    <div className="flex gap-1 mt-1.5 flex-wrap">
                      {(h.categories || []).slice(0, 3).map((c) => (
                        <span key={c} style={{ backgroundColor: catStyle(c).bg, color: catStyle(c).text }} className="text-[11px] px-2 py-0.5 rounded-full">{c}</span>
                      ))}
                    </div>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}

        {tab === "browse" && activeHouseId && activeHouse && (
          <div>
            {!checkout && (
              <>
                <button onClick={() => setActiveHouseId(null)} className="flex items-center gap-1 text-sm text-stone-500 mb-3">
                  <ArrowRight size={16} /> رجوع
                </button>
                <div style={{ backgroundColor: catStyle((activeHouse.categories || [])[0]).solid }} className="w-full h-24 rounded-2xl flex items-center justify-center mb-3">
                  <img src={LOGO_SRC} alt="" className="w-12 h-12 object-contain" />
                </div>
                <div className="font-semibold text-lg text-stone-900 mb-1">{activeHouse.name}</div>
                <div className="text-xs text-stone-500 mb-1">{activeHouse.description}</div>
                <div className="text-sm text-stone-500 flex items-center gap-3 mb-3">
                  <span className="flex items-center gap-1"><MapPin size={12} />{activeHouse.area}</span>
                  {activeHouse.phone && <span className="flex items-center gap-1"><Phone size={12} />{activeHouse.phone}</span>}
                </div>

                {houseCats.length > 0 && (
                  <div className="flex gap-4 border-b border-stone-200 mb-3 text-sm">
                    {houseCats.map((c) => (
                      <button key={c} onClick={() => setHouseTab(c)}
                        style={houseTab === c ? { borderColor: catStyle(c).solid, color: catStyle(c).text } : {}}
                        className={`pb-2 ${houseTab === c ? "border-b-2 font-medium" : "text-stone-400"}`}>
                        {c}
                      </button>
                    ))}
                  </div>
                )}

                <div className="flex flex-col gap-2 mb-20">
                  {houseItems.filter((it) => it.category === houseTab).map((it) => {
                    const inCart = cart.find((c) => c.itemId === it.id);
                    return (
                      <div key={it.id} className="flex items-center gap-3 bg-white border border-stone-200 rounded-xl p-2 shadow-sm">
                        <div style={{ backgroundColor: catStyle(it.category).bg }} className="w-12 h-12 rounded-lg flex items-center justify-center flex-shrink-0">
                          <Package size={18} style={{ color: catStyle(it.category).text }} />
                        </div>
                        <div className="flex-1">
                          <div className="text-base font-semibold text-stone-900">{it.name}</div>
                          <div className="text-sm text-stone-500">متوفر: {it.qty} · <span style={{ color: PALETTE.orangeDark, fontWeight: 600 }}>{it.price.toLocaleString()} ل.س</span></div>
                        </div>
                        {inCart ? (
                          <div className="flex items-center gap-2 bg-stone-100 rounded-lg px-2 py-1">
                            <button onClick={() => changeQty(it.id, -1)}><Minus size={14} /></button>
                            <span className="text-sm font-medium w-4 text-center">{inCart.qty}</span>
                            <button onClick={() => changeQty(it.id, 1)}><Plus size={14} style={{ color: PALETTE.orange }} /></button>
                          </div>
                        ) : (
                          <button onClick={() => addToCart(it.id)} aria-label={`إضافة ${it.name}`}
                            style={primaryBtn}
                            className="w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0">
                            <Plus size={16} />
                          </button>
                        )}
                      </div>
                    );
                  })}
                </div>

                {cartCount > 0 && (
                  <button onClick={() => setCheckout(true)} style={primaryBtn}
                    className="fixed bottom-20 left-1/2 -translate-x-1/2 max-w-[280px] w-[85%] rounded-xl py-3 flex items-center justify-center gap-2 text-sm font-medium shadow-lg">
                    <ShoppingCart size={16} /> السلة ({cartCount} صنف)
                  </button>
                )}
              </>
            )}

            {checkout && !orderDone && (
              <div>
                <button onClick={() => setCheckout(false)} className="flex items-center gap-1 text-sm text-stone-500 mb-3">
                  <ArrowRight size={16} /> رجوع
                </button>
                <div className="font-semibold text-lg text-stone-900 mb-3">السلة — {activeHouse.name}</div>
                <div className="flex flex-col gap-2 mb-4">
                  {cartLines.map((l) => (
                    <div key={l.id} className="flex items-center gap-3 bg-white border border-stone-200 rounded-xl p-2 shadow-sm">
                      <div className="flex-1">
                        <div className="text-base font-semibold text-stone-900">{l.name}</div>
                        <div className="text-xs text-stone-500">{l.price.toLocaleString()} ل.س</div>
                      </div>
                      <div className="flex items-center gap-2 bg-stone-100 rounded-lg px-2 py-1">
                        <button onClick={() => changeQty(l.id, -1)}><Minus size={14} /></button>
                        <span className="text-sm font-medium w-4 text-center">{l.qty}</span>
                        <button onClick={() => changeQty(l.id, 1)}><Plus size={14} style={{ color: PALETTE.orange }} /></button>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="text-xs text-stone-500 mb-1">عنوان التوصيل</div>
                <textarea value={address} onChange={(e) => setAddress(e.target.value)}
                  placeholder="الحي، الشارع، أقرب معلم..." rows={2}
                  className="w-full bg-white border border-stone-200 rounded-xl p-3 text-sm mb-3 outline-none placeholder-stone-400" />

                <div className="text-xs text-stone-500 mb-1">ملاحظة (اختياري)</div>
                <input value={note} onChange={(e) => setNote(e.target.value)}
                  placeholder="مثلاً: بدون بصل"
                  className="w-full bg-white border border-stone-200 rounded-xl p-3 text-sm mb-3 outline-none placeholder-stone-400" />

                <div className="bg-white border border-stone-200 rounded-xl p-3 text-sm mb-4 flex items-center gap-2 text-stone-600">
                  <span>طريقة الدفع:</span><span className="font-medium">كاش عند الاستلام</span>
                </div>

                <div className="flex justify-between text-sm text-stone-500 mb-1">
                  <span>المجموع</span><span>{cartTotal.toLocaleString()} ل.س</span>
                </div>
                <div className="flex justify-between text-sm text-stone-500 mb-2">
                  <span>التوصيل</span><span>{deliveryFee.toLocaleString()} ل.س</span>
                </div>
                <div className="flex justify-between font-medium text-stone-900 mb-4">
                  <span>الإجمالي</span><span style={{ color: PALETTE.orangeDark }}>{(cartTotal + deliveryFee).toLocaleString()} ل.س</span>
                </div>

                {!address.trim() && (
                  <div className="text-xs text-red-600 mb-2">لازم إدخال عنوان التوصيل قبل التأكيد.</div>
                )}
                <button onClick={confirmOrder} style={primaryBtn}
                  className="w-full rounded-xl py-3 font-semibold text-base">
                  تأكيد الطلب
                </button>
              </div>
            )}

            {orderDone && (
              <div className="text-center py-16">
                <div style={{ backgroundColor: catStyle("مونة").bg, color: catStyle("مونة").text }} className="w-14 h-14 rounded-full flex items-center justify-center mx-auto mb-3">
                  <Check size={26} />
                </div>
                <div className="font-medium text-stone-900 mb-1">تم إرسال الطلب!</div>
                <div className="text-sm text-stone-500 mb-5">بيت الطبخ رح يستلم الطلب ويجهزه.</div>
                <button onClick={() => { setActiveHouseId(null); setCheckout(false); setOrderDone(false); }}
                  style={{ color: PALETTE.orangeDark }} className="text-sm font-medium">رجوع للتصفح</button>
              </div>
            )}
          </div>
        )}

        {tab === "kitchen" && (
          <div>
            {!myHouseId || !houses.find((h) => h.id === myHouseId) ? (
              <div>
                <div className="font-semibold text-lg text-stone-900 mb-1">تسجيل مطبخ جديد</div>
                <div className="text-sm text-stone-500 mb-4">سجّل مطبخك مرة وحدة، وبعدين هاد التبويب رح يصير لوحة تحكمك الخاصة فيه.</div>

                <div className="text-xs text-stone-500 mb-1">اسم بيت الطبخ</div>
                <input value={regName} onChange={(e) => setRegName(e.target.value)}
                  placeholder="مثال: مطبخ أبو خالد"
                  className="w-full bg-white border border-stone-200 rounded-xl p-3 text-sm mb-3 outline-none placeholder-stone-400" />

                <div className="text-xs text-stone-500 mb-1">وصف قصير</div>
                <input value={regDesc} onChange={(e) => setRegDesc(e.target.value)}
                  placeholder="وصف مختصر عن الاختصاص"
                  className="w-full bg-white border border-stone-200 rounded-xl p-3 text-sm mb-3 outline-none placeholder-stone-400" />

                <div className="text-xs text-stone-500 mb-1">المنطقة / المدينة</div>
                <input value={regArea} onChange={(e) => setRegArea(e.target.value)}
                  placeholder="مثال: دمشق - المزة"
                  className="w-full bg-white border border-stone-200 rounded-xl p-3 text-sm mb-3 outline-none placeholder-stone-400" />

                <div className="text-xs text-stone-500 mb-1">رقم الهاتف</div>
                <input value={regPhone} onChange={(e) => setRegPhone(e.target.value)}
                  placeholder="09xxxxxxxx"
                  className="w-full bg-white border border-stone-200 rounded-xl p-3 text-sm mb-4 outline-none placeholder-stone-400" />

                <div className="text-xs text-stone-500 mb-2">الاختصاص (يمكن اختيار أكتر من وحدة)</div>
                <div className="flex flex-wrap gap-2 mb-5">
                  {CATS.map((c) => (
                    <button key={c.id} onClick={() => toggleRegCat(c.id)}
                      style={regCats.includes(c.id) ? { backgroundColor: catStyle(c.id).solid, color: "#fff" } : {}}
                      className={`text-xs px-3 py-1.5 rounded-full ${regCats.includes(c.id) ? "" : "bg-white border border-stone-200 text-stone-500"}`}>
                      {c.label}
                    </button>
                  ))}
                </div>

                <div className="text-xs text-stone-500 mb-2">الأصناف</div>
                <div className="flex flex-col gap-3 mb-3">
                  {regItems.map((it, idx) => (
                    <div key={idx} className="bg-white border border-stone-200 rounded-xl p-3 flex flex-col gap-2">
                      <div className="flex justify-between items-center">
                        <span className="text-xs text-stone-400">صنف {idx + 1}</span>
                        {regItems.length > 1 && (
                          <button onClick={() => removeRegItemRow(idx)} className="text-stone-400"><Trash2 size={14} /></button>
                        )}
                      </div>
                      <input value={it.name} onChange={(e) => updateRegItem(idx, "name", e.target.value)}
                        placeholder="اسم الصنف (مثلاً: مكدوس)"
                        className="w-full bg-stone-50 border border-stone-200 rounded-lg p-2 text-sm outline-none placeholder-stone-400" />
                      <select value={it.category} onChange={(e) => updateRegItem(idx, "category", e.target.value)}
                        className="w-full bg-stone-50 border border-stone-200 rounded-lg p-2 text-sm outline-none">
                        <option value="">اختيار التصنيف</option>
                        {(regCats.length ? regCats : CATS.map((c) => c.id)).map((c) => (
                          <option key={c} value={c}>{c}</option>
                        ))}
                      </select>
                      <div className="flex gap-2">
                        <input value={it.price} onChange={(e) => updateRegItem(idx, "price", e.target.value)}
                          type="number" placeholder="السعر (ل.س)"
                          className="w-1/2 bg-stone-50 border border-stone-200 rounded-lg p-2 text-sm outline-none placeholder-stone-400" />
                        <input value={it.qty} onChange={(e) => updateRegItem(idx, "qty", e.target.value)}
                          type="number" placeholder="الكمية"
                          className="w-1/2 bg-stone-50 border border-stone-200 rounded-lg p-2 text-sm outline-none placeholder-stone-400" />
                      </div>
                    </div>
                  ))}
                </div>
                <button onClick={addRegItemRow} style={{ color: PALETTE.orangeDark }} className="text-sm font-medium mb-4 flex items-center gap-1">
                  <Plus size={14} /> إضافة صنف آخر
                </button>

                {regError && <div className="text-xs text-red-600 mb-3">{regError}</div>}

                <button onClick={submitRegistration} style={primaryBtn}
                  className="w-full rounded-xl py-3 font-semibold text-base">
                  تسجيل بيت الطبخ
                </button>
              </div>
            ) : (
              <div>
                {(() => {
                  const myHouse = houses.find((h) => h.id === myHouseId);
                  const myItems = items.filter((it) => it.houseId === myHouseId);
                  const myKitchenOrders = orders.filter((o) => o.houseId === myHouseId);
                  const status = myHouse.status || "معتمد";
                  return (
                    <>
                      <div className="flex items-center justify-between mb-1">
                        <div className="font-semibold text-lg text-stone-900">{myHouse.name}</div>
                        {myHouse.featured && (
                          <span style={{ backgroundColor: catStyle("حلويات").bg, color: catStyle("حلويات").text }} className="text-xs px-2 py-1 rounded-full flex items-center gap-1">
                            <Star size={11} fill={catStyle("حلويات").text} /> مميز
                          </span>
                        )}
                      </div>
                      <span style={status === "معتمد" ? { backgroundColor: catStyle("مونة").bg, color: catStyle("مونة").text } : { backgroundColor: catStyle("حلويات").bg, color: catStyle("حلويات").text }}
                        className="text-xs px-2 py-1 rounded-full inline-block mb-5">
                        {status === "معتمد" ? "مطبخك ظاهر بالتصفح" : "بانتظار موافقة الإدارة"}
                      </span>

                      <div className="text-sm font-semibold text-stone-700 mb-2">أصنافك ({myItems.length})</div>
                      <div className="flex flex-col gap-2 mb-4">
                        {myItems.map((it) => (
                          <div key={it.id} className="flex items-center gap-3 bg-white border border-stone-200 rounded-xl p-2 shadow-sm">
                            <div style={{ backgroundColor: catStyle(it.category).bg }} className="w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0">
                              <Package size={16} style={{ color: catStyle(it.category).text }} />
                            </div>
                            <div className="flex-1">
                              <div className="text-sm font-medium text-stone-900">{it.name}</div>
                              <div className="text-xs text-stone-500">{it.category} · {it.price.toLocaleString()} ل.س · متوفر {it.qty}</div>
                            </div>
                            <button onClick={() => deleteKitchenItem(it.id)} className="text-stone-400"><Trash2 size={15} /></button>
                          </div>
                        ))}
                      </div>

                      <div className="bg-white border border-stone-200 rounded-xl p-3 mb-6 shadow-sm">
                        <div className="text-xs text-stone-500 mb-2">إضافة صنف جديد</div>
                        <input value={kNewItem.name} onChange={(e) => setKNewItem({ ...kNewItem, name: e.target.value })}
                          placeholder="اسم الصنف"
                          className="w-full bg-stone-50 border border-stone-200 rounded-lg p-2 text-sm mb-2 outline-none placeholder-stone-400" />
                        <select value={kNewItem.category} onChange={(e) => setKNewItem({ ...kNewItem, category: e.target.value })}
                          className="w-full bg-stone-50 border border-stone-200 rounded-lg p-2 text-sm mb-2 outline-none">
                          <option value="">اختيار التصنيف</option>
                          {CATS.map((c) => <option key={c.id} value={c.id}>{c.label}</option>)}
                        </select>
                        <div className="flex gap-2 mb-2">
                          <input value={kNewItem.price} onChange={(e) => setKNewItem({ ...kNewItem, price: e.target.value })}
                            type="number" placeholder="السعر"
                            className="w-1/2 bg-stone-50 border border-stone-200 rounded-lg p-2 text-sm outline-none placeholder-stone-400" />
                          <input value={kNewItem.qty} onChange={(e) => setKNewItem({ ...kNewItem, qty: e.target.value })}
                            type="number" placeholder="الكمية"
                            className="w-1/2 bg-stone-50 border border-stone-200 rounded-lg p-2 text-sm outline-none placeholder-stone-400" />
                        </div>
                        <button onClick={addKitchenItem} style={primaryBtn} className="w-full rounded-lg py-2 text-sm font-medium">إضافة</button>
                      </div>

                      <div className="text-sm font-semibold text-stone-700 mb-2">طلباتك ({myKitchenOrders.length})</div>
                      {myKitchenOrders.length === 0 && (
                        <div className="text-center text-stone-400 text-sm py-10">
                          <ClipboardList className="mx-auto mb-2" size={26} />
                          ما في طلبات لهلق.
                        </div>
                      )}
                      <div className="flex flex-col gap-3">
                        {myKitchenOrders.map((o) => (
                          <div key={o.id} className="bg-white border border-stone-200 rounded-2xl p-3 shadow-sm">
                            <div className="flex justify-between items-center mb-2">
                              <span style={o.status === "تم التسليم" ? { backgroundColor: catStyle("مونة").bg, color: catStyle("مونة").text } : { backgroundColor: catStyle("حلويات").bg, color: catStyle("حلويات").text }}
                                className="text-xs px-2 py-1 rounded-full">
                                {o.status}
                              </span>
                              <span className="text-xs text-stone-400">{new Date(o.createdAt).toLocaleString("ar")}</span>
                            </div>
                            <div className="text-sm text-stone-700 mb-1">
                              {o.items.map((l) => `${l.name} ×${l.qty}`).join("، ")}
                            </div>
                            <div className="text-xs text-stone-500 mb-1">العنوان: {o.address}</div>
                            {o.note && <div className="text-xs text-stone-500 mb-1">ملاحظة: {o.note}</div>}
                            <div className="text-sm font-medium mb-2" style={{ color: PALETTE.orangeDark }}>{o.total.toLocaleString()} ل.س</div>
                            <button onClick={() => toggleOrderStatus(o.id)} style={{ color: PALETTE.orangeDark }} className="text-xs font-medium">
                              تغيير الحالة إلى {o.status === "قيد التحضير" ? "تم التسليم" : "قيد التحضير"}
                            </button>
                          </div>
                        ))}
                      </div>
                    </>
                  );
                })()}
              </div>
            )}
          </div>
        )}

        {tab === "admin" && (
          <div>
            <div className="font-semibold text-lg text-stone-900 mb-4 flex items-center gap-2">
              <ShieldCheck size={20} /> لوحة الإدارة
            </div>

            {!adminUnlocked ? (
              <div className="bg-white border border-stone-200 rounded-xl p-4 shadow-sm">
                <div className="text-sm text-stone-600 mb-3 flex items-center gap-2">
                  <Lock size={14} /> هاي مساحة محمية — هاد قفل تجريبي بالمعاينة فقط، الموقع الحقيقي رح يكون فيه حساب دخول آمن فعليًا.
                </div>
                <input value={adminPass} onChange={(e) => setAdminPass(e.target.value)} type="password"
                  placeholder="كلمة السر"
                  className="w-full bg-stone-50 border border-stone-200 rounded-lg p-3 text-base mb-3 outline-none placeholder-stone-400" />
                {adminError && <div className="text-xs text-red-600 mb-3">{adminError}</div>}
                <button onClick={checkAdminPass} style={primaryBtn} className="w-full rounded-xl py-3 font-semibold text-base">دخول</button>
              </div>
            ) : (
              <div>
                <div className="text-sm font-semibold text-stone-700 mb-2">بانتظار الموافقة ({pendingHouses.length})</div>
                {pendingHouses.length === 0 && (
                  <div className="text-sm text-stone-400 mb-5">ما في تسجيلات جديدة بانتظار المراجعة.</div>
                )}
                <div className="flex flex-col gap-3 mb-6">
                  {pendingHouses.map((h) => (
                    <div key={h.id} className="bg-white border border-stone-200 rounded-xl p-3 shadow-sm">
                      <div className="font-semibold text-stone-900 mb-1">{h.name}</div>
                      <div className="text-sm text-stone-500 mb-3">{h.area} · {(h.categories || []).join("، ")}</div>
                      <div className="flex gap-2">
                        <button onClick={() => approveHouse(h.id)} style={{ backgroundColor: catStyle("مونة").solid, color: "#fff" }}
                          className="flex-1 rounded-lg py-2 text-sm font-medium">اعتماد</button>
                        <button onClick={() => rejectHouse(h.id)} style={{ backgroundColor: catStyle("مناسف وعزايم").solid, color: "#fff" }}
                          className="flex-1 rounded-lg py-2 text-sm font-medium">رفض</button>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="text-sm font-semibold text-stone-700 mb-2">البيوت المعتمدة ({approvedHouses.length})</div>
                <div className="flex flex-col gap-3">
                  {approvedHouses.map((h) => (
                    <div key={h.id} className="bg-white border border-stone-200 rounded-xl p-3 shadow-sm flex items-center justify-between">
                      <div>
                        <div className="font-semibold text-stone-900 flex items-center gap-1">
                          {h.name}
                          {h.featured && <Star size={13} fill={PALETTE.gold} style={{ color: PALETTE.gold }} />}
                        </div>
                        <div className="text-sm text-stone-500">{h.area}</div>
                      </div>
                      <button onClick={() => toggleFeatured(h.id)}
                        style={h.featured ? { backgroundColor: catStyle("حلويات").solid, color: "#fff" } : {}}
                        className={`text-xs px-3 py-1.5 rounded-full ${h.featured ? "" : "bg-stone-100 text-stone-600"}`}>
                        {h.featured ? "مميز ✓" : "تمييز"}
                      </button>
                    </div>
                  ))}
                </div>

                <div className="border-t border-stone-200 my-6"></div>

                <div className="text-sm font-semibold text-stone-700 mb-2">إنشاء إعلان جديد</div>
                <div className="bg-white border border-stone-200 rounded-xl p-3 mb-4 shadow-sm">
                  <select value={adHouseId} onChange={(e) => setAdHouseId(e.target.value)}
                    className="w-full bg-stone-50 border border-stone-200 rounded-lg p-2 text-sm mb-2 outline-none">
                    <option value="">اختيار المطبخ المُعلِن</option>
                    {approvedHouses.map((h) => <option key={h.id} value={h.id}>{h.name}</option>)}
                  </select>
                  <input value={adText} onChange={(e) => setAdText(e.target.value)}
                    placeholder="نص الإعلان (مثلاً: خصم 20% على المكدوس هالأسبوع)"
                    className="w-full bg-stone-50 border border-stone-200 rounded-lg p-2 text-sm mb-2 outline-none placeholder-stone-400" />
                  <div className="flex gap-2 mb-3">
                    {Object.keys(AD_PACKAGES).map((p) => (
                      <button key={p} onClick={() => setAdPackage(p)}
                        style={adPackage === p ? { backgroundColor: AD_PACKAGES[p].solid, color: "#fff" } : {}}
                        className={`flex-1 text-xs py-2 rounded-lg ${adPackage === p ? "" : "bg-stone-100 text-stone-600"}`}>
                        {p} · {AD_PACKAGES[p].days} أيام
                      </button>
                    ))}
                  </div>
                  <button onClick={createAd} style={primaryBtn} className="w-full rounded-lg py-2 text-sm font-medium">نشر الإعلان</button>
                </div>

                <div className="text-sm font-semibold text-stone-700 mb-2">الإعلانات الفعّالة ({activeAds.length})</div>
                {activeAds.length === 0 && (
                  <div className="text-sm text-stone-400 mb-2">ما في إعلانات فعّالة حاليًا.</div>
                )}
                <div className="flex flex-col gap-2">
                  {activeAds.map((a) => (
                    <div key={a.id} className="bg-white border border-stone-200 rounded-xl p-3 shadow-sm flex items-center justify-between gap-2">
                      <div className="min-w-0">
                        <div className="text-sm font-medium text-stone-900 flex items-center gap-2">
                          <span style={{ color: AD_PACKAGES[a.pkg]?.solid }}>{a.pkg}</span> · {a.houseName}
                        </div>
                        <div className="text-xs text-stone-500 truncate">{a.text}</div>
                        <div className="text-[11px] text-stone-400">ينتهي {new Date(a.expiresAt).toLocaleDateString("ar")}</div>
                      </div>
                      <button onClick={() => deleteAd(a.id)} className="text-stone-400 flex-shrink-0"><Trash2 size={15} /></button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="flex border-t border-stone-200 bg-white">
        {[
          { id: "browse", label: "تصفح", icon: Home },
          { id: "kitchen", label: "مطبخي", icon: Package },
          { id: "admin", label: "الإدارة", icon: ShieldCheck },
        ].map((t) => (
          <button key={t.id} onClick={() => { setTab(t.id); setActiveHouseId(null); }}
            style={{ color: tab === t.id ? PALETTE.orange : "#a8a29e" }}
            className="flex-1 py-3 flex flex-col items-center gap-1 text-xs">
            <t.icon size={18} />
            {t.label}
          </button>
        ))}
      </div>
    </div>
  );
}
